'use strict';
const runtimeConfig=window.CLOUDGUARD_CONFIG||{mode:'local',localApiBase:'/api'};
const state={page:'agent',token:sessionStorage.getItem('fj_token')||'',awsToken:sessionStorage.getItem('fj_aws_token')||'',awsConnected:false,cloud:null,cloudLastRun:null,data:null,config:null,agentScenario:'security_baseline',agentRunning:false,configFilter:{status:'all',service:'all',query:''}};
const pages={agent:['智能安全治理 Agent','AGENT / SECURITY GOVERNANCE'],dashboard:['安全运营总览','OPERATIONS / DASHBOARD'],architecture:['系统架构','PLATFORM / ARCHITECTURE'],resources:['云资源中心','PLATFORM / CLOUD RESOURCES'],copilot:['智能运营','SECURITY / AI COPILOT'],customers:['客户接入','CUSTOMERS / ONBOARDING'],catalog:['服务方案','SERVICES / PROCUREMENT'],projects:['交付项目','DELIVERY / PROJECTS'],findings:['安全发现','SECURITY / FINDINGS'],incidents:['事件响应','SECURITY / INCIDENT RESPONSE'],identity:['身份治理','SECURITY / IDENTITY'],protection:['数据保护','SECURITY / DATA PROTECTION'],compliance:['合规控制','GOVERNANCE / CONTROLS'],evidence:['证据中心','GOVERNANCE / EVIDENCE'],reports:['报告中心','OPERATIONS / REPORTS'],audit:['审计日志','GOVERNANCE / AUDIT LOG']};
const nav=[{group:'智能治理',items:[['agent','✦','安全治理 Agent'],['dashboard','◫','安全运营总览'],['architecture','⌘','系统架构']]},{group:'业务与交付',items:[['customers','♙','客户接入'],['resources','◇','云资源中心'],['catalog','▦','服务方案'],['projects','◆','交付项目']]},{group:'安全治理',items:[['copilot','AI','智能运营'],['findings','◉','安全发现'],['incidents','⚡','事件响应'],['identity','♜','身份治理'],['protection','▣','数据保护'],['compliance','▤','Config 合规']]},{group:'运营记录',items:[['evidence','⌑','证据中心'],['reports','▧','报告中心'],['audit','⌕','审计日志']]}];
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const fmt=d=>d?new Date(d).toLocaleString('zh-CN'):'—';
const tag=(type,text)=>`<span class="tag tag-${type}">${esc(text)}</span>`;
const section=(title,sub,action='')=>`<div class="section-head"><div><h2>${title}</h2><p>${sub}</p></div>${action}</div>`;
const metric=(label,value,note,color='#e8f2ff')=>`<article class="card metric" style="--metric-color:${color}"><div class="metric-label">${label}</div><div class="metric-value">${value}</div><div class="metric-note">${note}</div></article>`;
const progress=(v,cls='')=>`<div class="progress ${cls}"><span style="width:${Math.max(0,Math.min(100,v))}%"></span></div>`;
async function requestJson(base,path,options={},token=''){const headers={'Content-Type':'application/json',...(options.headers||{})};if(token)headers.Authorization=`Bearer ${token}`;const res=await fetch(`${String(base).replace(/\/$/,'')}${path}`,{...options,headers});let out;try{out=await res.json()}catch{out={error:await res.text()}}if(!res.ok)throw new Error(out.error||`请求失败 ${res.status}`);return out;}
async function api(path,options={}){try{return await requestJson(runtimeConfig.localApiBase||'/api',path,options,state.token)}catch(err){if(String(err.message).includes('登录')&&path!=='/auth/login')logout(false);throw err}}
async function cloudApi(path,options={}){if(state.awsConnected&&runtimeConfig.awsApiBase)return requestJson(runtimeConfig.awsApiBase,path,options,state.awsToken);return api(path,options)}
async function loadCloud(){if(!state.awsConnected||!runtimeConfig.awsApiBase){state.cloud=null;return}const get=p=>cloudApi(p).catch(error=>({error:error.message}));const [topology,resources,protection,evidence,configMonitoring]=await Promise.all([get('/platform/topology'),get('/resources'),get('/data-protection'),get('/evidence'),get('/config-monitoring')]);state.cloud={topology,resources,protection,evidence,configMonitoring,observedAt:new Date().toISOString()}}
async function load(){state.data=await api('/bootstrap');await loadCloud();renderChrome();render();}
function renderChrome(){$('#tenantName').textContent=state.awsConnected?'福驾科技 · AWS实时数据':'福驾科技 · 本地演示';$('#avatar').textContent=state.data.user.name.slice(0,2);$('#awsConnectButton').textContent=state.awsConnected?'☁ AWS 已连接':'☁ 本地适配器';$('#awsConnectButton').classList.toggle('connected',state.awsConnected);$('#pageTitle').textContent=pages[state.page][0];$('#breadcrumb').textContent=pages[state.page][1];$('#nav').innerHTML=nav.map(g=>`<div class="nav-group">${g.group}</div>${g.items.map(i=>`<button class="nav-item ${state.page===i[0]?'active':''}" data-page="${i[0]}"><span class="nav-icon">${i[1]}</span>${i[2]}</button>`).join('')}`).join('');document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));}
function navigate(p){state.page=p;location.hash=p;$('#pageTitle').textContent=pages[p][0];$('#breadcrumb').textContent=pages[p][1];renderChrome();render();$('#sidebar').classList.remove('open');window.scrollTo(0,0);}
function executionGuide(){const guides={agent:['Agent执行','选择治理场景','调用AWS治理工具','生成工单与证据','输出安全报告'],dashboard:['运营闭环','客户接入','服务开通','项目交付','安全运营','报告审计'],architecture:['架构落地','用户安全接入','五层纵深防护','自动化函数编排','业务资源与数据保护'],resources:['资源运营','同步云资源清单','检查健康与加密','查看成本和告警','进入整改流程'],copilot:['智能分析','聚合实时运营数据','计算风险与关联信号','生成可解释建议','由人员审批执行'],customers:['客户接入','创建客户档案','完成 SMB 初筛','配置跨账户角色','同步 AWS 数据'],catalog:['采购执行','选择已接入客户','填写安全需求','确认推荐产品','生成订单与项目'],projects:['交付执行','点击当前里程碑','更新为客户已验收','启动下一里程碑','M5 完成项目'],findings:['发现处理','AWS Webhook / 手工录入','确认严重级别与资源','创建安全事件','跟踪整改'],incidents:['响应执行','按 Finding 生成计划','DRY_RUN 验证','完成真实处置并确认','自动写入时间线'],identity:['身份治理','应用 MFA/RBAC/SCP 基线','定期访问复核','记录保留/降权/撤销','关联工单证据'],protection:['数据保护','扫描加密资产','检查KMS轮换','分析Macie发现','采集保护证据'],compliance:['合规执行','选择控制项','评估合规状态','关联真实证据','汇总合规率'],reports:['报告执行','汇总实时业务数据','生成安全治理报告','下载 JSON','归档并发送客户'],evidence:['证据管理','自动采集AWS证据','计算SHA-256哈希','执行完整性验证','供审计报告引用'],audit:['审计追溯','自动记录关键操作','按对象核对变更','关联工单与证据','审计复核']};const g=guides[state.page];return `<div class="execution-guide"><div><span>HOW IT WORKS</span><strong>${g[0]}</strong></div><div class="execution-steps">${g.slice(1).map((x,i)=>`<div><b>${i+1}</b>${x}</div>`).join('<i>→</i>')}</div></div>`;}
function render(){const fn={agent:agentPage,dashboard,architecture:architecturePage,resources:resourcesPage,copilot:copilotPage,customers,catalog,projects,findings,incidents,identity,protection:protectionPage,compliance,evidence:evidencePage,reports,audit}[state.page];$('#app').innerHTML=executionGuide()+fn();bind();}
function customerName(id){return state.data.customers.find(c=>c.id===id)?.name||'未知客户';}
function configTrendChart(snapshots,compact=false){if(!snapshots?.length)return '<div class="empty-state">暂无趋势数据</div>';const w=compact?430:700,h=compact?125:180,pad=compact?18:28,min=Math.min(...snapshots.map(x=>x.score),55),max=100,points=snapshots.map((x,i)=>{const px=pad+i*(w-pad*2)/Math.max(1,snapshots.length-1),py=h-pad-(x.score-min)/(max-min)*(h-pad*2);return {x:px,y:py,score:x.score,date:new Date(x.capturedAt).toLocaleDateString('zh-CN',{month:'numeric',day:'numeric'})}});return `<div class="config-chart"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Config 合规率趋势"><defs><linearGradient id="configArea" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#1677ff" stop-opacity=".28"/><stop offset="1" stop-color="#1677ff" stop-opacity=".02"/></linearGradient></defs><line x1="${pad}" y1="${h-pad}" x2="${w-pad}" y2="${h-pad}" stroke="#dce5ec"/><polygon points="${pad},${h-pad} ${points.map(p=>`${p.x},${p.y}`).join(' ')} ${w-pad},${h-pad}" fill="url(#configArea)"/><polyline points="${points.map(p=>`${p.x},${p.y}`).join(' ')}" fill="none" stroke="#1677ff" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${points.map((p,i)=>`<circle cx="${p.x}" cy="${p.y}" r="4" fill="#fff" stroke="#1677ff" stroke-width="2"/><text x="${p.x}" y="${p.y-10}" text-anchor="middle" font-size="9" fill="#24445d" font-weight="700">${p.score}%</text>${!compact||i===0||i===points.length-1?`<text x="${p.x}" y="${h-3}" text-anchor="middle" font-size="8" fill="#789">${p.date}</text>`:''}`).join('')}</svg></div>`;}
function agentPage(){const scenarios=[['security_baseline','🛡️','安全基线评估','Config 40规则 · Security Hub · 风险清单'],['identity_governance','🔐','身份与密钥治理','IAM Identity Center · MFA · KMS轮换'],['threat_response','⚡','威胁检测与响应','GuardDuty关联 · 自动整改 · SNS通知'],['data_protection','▣','数据保护检查','KMS加密 · Macie扫描 · 证据采集'],['compliance_audit','▤','合规审计报告','Config评估 · Audit Manager · 报告']];const links={security_baseline:[['compliance','Config监控'],['findings','安全发现']],identity_governance:[['identity','身份治理']],threat_response:[['findings','安全发现'],['incidents','事件响应']],data_protection:[['protection','数据保护'],['evidence','证据中心']],compliance_audit:[['compliance','Config合规'],['evidence','证据中心'],['reports','报告中心']]};const last=state.data.agentRuns[0],scenario=state.data.agentScenarios[state.agentScenario];return `<div class="agent-product-header"><div class="agent-logo">✦</div><div><h2>福驾科技智能安全治理 Agent</h2><p>基于安全架构基线与实时运营数据，编排 AWS 原生安全服务完成评估、整改、取证和报告</p></div><span class="agent-env"><i></i> 已连接 3 个 AWS 账户</span></div>${state.cloudLastRun?`<div class="cloud-run-result"><div><span class="live-pulse"></span><b>AWS云端动作已完成</b><small>${esc(state.cloudLastRun.action||state.cloudLastRun.scenario||'governance')} · ${fmt(state.cloudLastRun.completedAt)}</small></div><div><span>执行引擎</span><b>${esc(state.cloudLastRun.engine||'aws-native-collector')}</b></div><div><span>证据ID</span><b>${esc(state.cloudLastRun.evidenceId||'审批工单模式')}</b></div></div>`:''}<div class="agent-workbench"><aside class="agent-controls"><section class="agent-panel"><h3>⌁ 选择治理场景</h3><div class="scenario-list">${scenarios.map(s=>`<button class="scenario-item ${state.agentScenario===s[0]?'active':''}" data-scenario="${s[0]}"><span>${s[1]}</span><div><b>${s[2]}</b><small>${s[3]}</small></div></button>`).join('')}</div><div class="agent-shortcuts"><span>相关功能</span>${links[state.agentScenario].map(x=>`<button data-page-link="${x[0]}">${x[1]} →</button>`).join('')}</div><textarea id="agentPrompt" placeholder="输入额外治理要求，例如：重点检查生产账户的公网暴露和加密状态…"></textarea><button class="agent-run-button" id="runAgent" ${state.agentRunning?'disabled':''}>${state.agentRunning?'◌ Agent 正在调用治理工具…':'✦ 启动安全治理 Agent'}</button></section><section class="agent-panel reasoning-panel"><h3>⚙ Agent 推理与工具调用</h3><div class="agent-steps">${(state.agentRunning?scenario.tools.map((t,i)=>({index:i+1,tool:t,label:toolLabel(t),status:i===0?'running':'pending'})):(last?.steps||scenario.tools.map((t,i)=>({index:i+1,tool:t,label:toolLabel(t),status:'pending'})))).map(s=>`<div class="agent-step ${s.status}"><span>${s.status==='completed'?'✓':s.status==='running'?'◌':s.index}</span><div><b>${esc(s.label)}</b><code>${esc(s.tool)}()</code></div></div>`).join('')}</div></section></aside><main class="agent-result">${last?agentReport(last):`<div class="agent-empty"><div>✦</div><h3>选择治理场景并启动 Agent</h3><p>Agent 将读取实时配置和安全数据，执行治理工具并在此生成可审计报告。</p></div>`}</main></div>`;}
function toolLabel(tool){return ({search_architecture_baseline:'检索安全架构与处置知识',config_rules:'执行AWS Config规则评估',query_security_posture:'查询威胁与安全态势',query_identity_status:'检查身份与访问状态',rotate_keys:'生成密钥轮换计划',correlate_findings:'关联多来源安全发现',auto_remediate:'生成并排队整改动作',query_data_protection:'检查数据加密与分类',collect_evidence:'采集并校验证据',map_audit_controls:'映射审计控制',create_work_order:'创建安全整改工单',notify_engineer:'通知值班安全工程师',generate_report:'生成治理报告'}[tool]||tool);}
function agentReport(run){const r=run.result,layerPages={'L1 账户治理':'customers','L2 身份安全':'identity','L3 检测响应':'findings','L4 数据保护':'protection','L5 合规审计':'compliance'};return `<article class="agent-report"><header><div><small>✦ AGENT EXECUTION REPORT</small><h2>${esc(run.scenarioName)}</h2><p>${esc(run.prompt)}</p></div>${tag('real','执行完成')}</header><div class="agent-report-metrics"><div><span>风险评分</span><b>${r.riskScore}<small>/100</small></b></div><div><span>Config合规率</span><b>${r.configScore}%</b></div><div><span>监控资源</span><b>${r.resources}</b></div><div><span>开放发现</span><b>${r.openFindings}</b></div></div><section><h3>五层安全治理覆盖</h3><div class="layer-status">${r.architectureCoverage.map(x=>`<button data-page-link="${layerPages[x.layer]}"><span>${esc(x.layer)}</span>${tag(x.status==='active'?'real':'demo',x.status==='active'?'运行中':'需优化')}<em>打开功能 →</em></button>`).join('')}</div></section><section><h3>工具调用链</h3><div class="tool-trace">${run.steps.map(s=>`<span>✓ ${esc(s.tool)}</span>`).join('')}</div></section><section><h3>优先风险与处理建议</h3><div class="agent-recommendations">${r.recommendations.map(x=>`<div><span>${tag(x.priority==='P0'?'gap':'demo',x.priority)}</span><div><b>${esc(x.title)}</b><p>${esc(x.action)}</p></div></div>`).join('')}</div></section><section class="agent-output-grid"><div><h3>执行产出</h3><p>证据快照 <b>${run.artifactIds.length}</b> 份</p><p>整改工单 <b>${run.workOrderIds.length}</b> 个</p><p>执行时间 ${fmt(run.completedAt)}</p><div class="toolbar"><button class="button button-ghost" data-page-link="evidence">查看证据</button><button class="button button-ghost" data-page-link="reports">查看报告</button></div></div><div><h3>当前项目</h3><p>${esc(r.project||'无进行中项目')}</p><button class="button button-ghost" data-page-link="projects">查看交付项目 →</button></div></section></article>`;}
function architecturePage(){const topology=state.data.topology,project=state.data.projects[0],deploy=project?.awsDeployment||[];const serviceStatus=name=>deploy.find(x=>x.service.includes(name))?.status||'planned';return `<div class="arch-hero"><div><span>SOLUTION ARCHITECTURE</span><h2>福驾科技安全治理系统架构</h2><p>围绕福驾科技云相机、云后厨、图片视频云存储等业务，采用五层纵深防护与事件驱动自动化，统一治理三个 AWS 账户。</p></div><div><b>3</b><span>AWS账户</span><b>247</b><span>受管资源</span></div></div>${cloudTelemetryPanel('topology')}<div class="implementation-banner"><div><b>当前实现</b><span>${esc(topology.implementation.runtime)} · ${esc(topology.implementation.persistence)}</span></div><div><b>AWS接入方式</b><span>${esc(topology.implementation.awsIntegration)}</span></div><div><b>生产目标</b><span>${esc(topology.implementation.productionTarget)}</span></div></div><div class="alert alert-warning" style="margin-top:10px">${esc(topology.implementation.disclaimer)}</div>${section('用户安全接入','运维人员与管理员通过统一认证访问治理平台')}<div class="arch-flow access-flow">${[['用户','运维 / 开发 / 管理员','customers'],['AWS WAF','Web攻击防护','architecture'],['Amazon API Gateway','统一API入口','architecture'],['Amazon Cognito','身份认证与MFA','identity'],['Amazon CloudFront','安全内容分发','architecture']].map((x,i)=>`${i?'<i>→</i>':''}<button data-page-link="${x[2]}"><strong>${x[0]}</strong><span>${x[1]}</span><em>打开功能 →</em></button>`).join('')}</div>${section('五层纵深安全治理','每层均对应可执行的治理函数与运行状态')}<div class="security-layers">${[
 ['L1','账户治理','AWS Organizations · SCP','config_rules','统一多账户边界与服务控制策略','active','customers'],['L2','身份安全','IAM Identity Center · MFA · SSO','rotate_keys','集中身份、最小权限和凭证轮换','active','identity'],['L3','检测响应','Security Hub · GuardDuty','auto_remediate','聚合威胁发现并编排自动响应','active','findings'],['L4','数据保护','AWS KMS · Amazon Macie','collect_evidence','加密业务数据并发现敏感信息','partial','protection'],['L5','合规审计','AWS Config · Audit Manager','generate_report','持续评估、自动采证和审计报告','active','compliance']
 ].map(x=>`<article class="security-layer ${x[5]}" data-page-link="${x[6]}"><span>${x[0]}</span><div><h3>${x[1]}</h3><b>${x[2]}</b><p>${x[4]}</p><button class="layer-action" data-arch-action="${x[3]}">${x[3]}() · 立即执行</button></div>${tag(x[5]==='active'?'real':'demo',x[5]==='active'?'运行中':'部署中')}<em>进入${x[1]} →</em></article>`).join('')}</div>${section('事件驱动自动化链路','高危发现从检测到通知和审计全程留痕')}<div class="automation-flow"><button data-page-link="findings"><b>Security Hub / GuardDuty</b><span>查看高危 Finding</span></button><i>→</i><button data-page-link="incidents"><b>Amazon EventBridge</b><span>进入事件响应</span></button><i>→</i><button data-arch-action="auto_remediate"><b>AWS Lambda</b><span>执行整改编排</span></button><i>→</i><button data-page-link="audit"><b>Amazon SNS</b><span>查看通知审计</span></button><i>→</i><button data-page-link="evidence"><b>CloudTrail + S3</b><span>验证审计证据</span></button></div>${section('业务与数据层','安全能力围绕真实工作负载部署，而不是独立展示')}<div class="resource-grid">${[['Amazon EC2 / EKS','云相机分析与后台服务'],['Aurora / RDS','订单与业务数据库'],['Amazon DocumentDB','设备与文档数据'],['Amazon DynamoDB','设备状态与事件'],['Amazon ElastiCache','缓存与会话'],['Amazon S3 / EBS','图片、视频和日志存储']].map(x=>`<button data-page-link="resources"><span class="resource-icon">◇</span><b>${x[0]}</b><small>${x[1]}</small><em>查看资源 →</em></button>`).join('')}</div>${section('平台服务运行状态','与交付项目中的部署组件同步')}<div class="card table-wrap"><table class="table"><thead><tr><th>AWS服务</th><th>在本系统中的作用</th><th>部署状态</th></tr></thead><tbody>${deploy.map(x=>`<tr><td><b>${esc(x.service)}</b></td><td>${esc(x.role)}</td><td>${tag(x.status==='active'?'real':x.status==='deploying'?'demo':'neutral',x.status==='active'?'已启用':x.status==='deploying'?'部署中':'计划中')}</td></tr>`).join('')}</tbody></table></div><div class="ops-strip"><button data-page-link="dashboard">Amazon CloudWatch · 监控告警</button><button data-page-link="audit">AWS CloudTrail · 全链路审计</button><button data-page-link="resources">AWS Cost Explorer · 成本可视</button><button data-page-link="projects">AWS CloudFormation · IaC交付</button><button data-page-link="identity">IAM最小权限 · 7×24值守</button></div>`;}
function dashboard(){const d=state.data.dashboard,cm=state.data.configMonitoring;return `<div class="hero"><span class="tag tag-real">LIVE APPLICATION</span><h2>福驾科技安全运营中心</h2><p>集中管理云环境接入、交付进度、安全发现、事件响应和持续合规。当前环境由托管服务团队持续运营，所有关键变更均保留审计记录。</p></div>${section('当前业务状态','实时业务数据 · 托管服务：博思云为')}<div class="grid grid-4">${metric('活跃客户',d.customers,'已完成接入')}${metric('进行中项目',d.activeProjects,'M0–M5 标准交付')}${metric('开放安全发现',d.openFindings,'待调查或整改',d.openFindings?'#ffe7e7':'#e5f8f1')}${metric('合规率',d.complianceRate===null?'未评估':`${d.complianceRate}%`,'仅统计已评估控制')}</div><div class="ai-summary"><div class="ai-score"><small>智能风险评分</small><strong>${state.data.aiInsights.riskScore}</strong><span>/ 100 · ${state.data.aiInsights.riskLevel}风险</span></div><div><span class="ai-label">✦ CLOUDGUARD INTELLIGENCE</span><h3>${state.data.aiInsights.insights[0]?.title||'当前未发现高优先级风险'}</h3><p>${state.data.aiInsights.insights[0]?.detail||'智能引擎已完成安全发现、事件和控制的联合分析。'}</p></div><button class="button ai-button" data-page-link="copilot">查看分析与建议 →</button></div>${section('AWS Config 持续合规监控',`最近评估 ${fmt(cm.summary.lastEvaluationAt)} · 下次评估 ${fmt(cm.summary.nextEvaluationAt)}`,'<button class="button button-ghost" data-page-link="compliance">打开监控中心 →</button>')}<div class="grid config-overview"><article class="card config-score-card"><div class="donut config-donut" style="--value:${cm.summary.score||0}"><strong>${cm.summary.score??'—'}%</strong></div><div><span class="small muted">资源合规率</span><h3>${cm.summary.compliantResources} / ${cm.summary.totalResources} 个资源合规</h3><p class="small muted">${cm.summary.nonCompliantResources} 不合规 · ${cm.summary.unknownResources} 未知</p></div></article><article class="card"><div class="flex between"><div><b>28 天合规趋势</b><p class="small muted">从 61% 提升至 ${cm.summary.score}%</p></div>${tag('real','持续记录')}</div>${configTrendChart(cm.snapshots,true)}</article><article class="card"><div class="flex between"><b>规则运行状态</b><span>${cm.summary.totalRules} 条</span></div><div class="config-rule-stats"><div><strong>${cm.summary.compliantRules}</strong><span>合规</span></div><div class="bad"><strong>${cm.summary.nonCompliantRules}</strong><span>不合规</span></div><div><strong>${cm.summary.autoRemediation}</strong><span>可自动整改</span></div></div><div class="alert alert-warning">${cm.nonCompliantResources.length} 个资源命中不合规规则，需进入整改队列。</div></article></div>${section('云安全服务运行状态','3 个账户的治理、检测、响应和合规组件')}<div class="card"><div class="architecture"><div class="arch-node"><b>AWS Organizations</b><br><small>3 个账户治理</small></div><span class="arch-arrow">→</span><div class="arch-node"><b>Security Hub</b><br><small>统一安全态势</small></div><span class="arch-arrow">→</span><div class="arch-node"><b>GuardDuty + Config</b><br><small>威胁与偏差检测</small></div><span class="arch-arrow">→</span><div class="arch-node"><b>EventBridge + Lambda</b><br><small>事件驱动响应</small></div><span class="arch-arrow">→</span><div class="arch-node"><b>Audit Manager</b><br><small>自动合规证据</small></div></div></div>${section('待处理工作','真实记录为空时不会生成虚假指标')}<div class="grid grid-2"><article class="card"><h3>最近安全发现</h3>${d.recentFindings.length?d.recentFindings.map(f=>`<div class="flex between" style="padding:9px 0;border-bottom:1px solid #edf1f4"><span class="small">${esc(f.type)}</span>${tag(f.severity>=7?'gap':'demo',`Severity ${f.severity}`)}</div>`).join(''):`<div class="empty-state"><strong>暂无安全发现</strong>通过“安全发现”手工录入或 AWS Webhook 接入。</div>`}</article><article class="card"><h3>最近交付项目</h3>${d.recentProjects.length?d.recentProjects.map(p=>`<div style="padding:9px 0"><div class="flex between small"><b>${esc(p.name)}</b><span>${p.progress}%</span></div>${progress(p.progress,'green')}</div>`).join(''):`<div class="empty-state"><strong>暂无交付项目</strong>完成客户接入后，在产品采购中创建订单。</div>`}</article></div>`;}
function partnerPage(){const lifecycle=[['01','发现与评估','访谈业务与技术团队、盘点 AWS 账户和工作负载、建立安全基线与优先级'],['02','架构与方案','将客户需求映射到 AWS 原生服务，输出目标架构、成本估算、实施范围和 SOW'],['03','自动化实施','使用 CloudFormation、Config 规则、SCP 和 Lambda Runbook 完成标准化部署'],['04','验证与移交','执行控制验证、事件演练、知识转移、客户验收并归档交付证据'],['05','持续运营','监控 Finding、响应事件、提供月度报告并持续优化安全和成本']];return `<div class="partner-hero"><div><span>AWS PARTNER VALUE</span><h2>博思云为：连接 AWS 原生能力与 SMB 业务成果</h2><p>博思云为作为 AWS 合作伙伴和解决方案提供商，理解福驾科技的业务风险，选择并组合合适的 AWS 服务，通过标准架构、自动化组件和托管运营，把 AWS 的产品能力转化为可验收、可运营、可持续改进的客户解决方案。</p></div><div class="partner-badge"><b>博思云为</b><span>AWS 合作伙伴</span><small>咨询 · 架构 · 实施 · 运营</small></div></div>
${section('三方协作模式','平台、合作伙伴与客户职责清晰分工')}<div class="three-party"><div class="party aws-party"><small>云平台与原生能力</small><strong>AWS</strong><p>提供 Organizations、Security Hub、GuardDuty、Config、KMS、Lambda 等云服务及最佳实践。</p></div><div class="party-link"><span>产品能力与技术支持</span>→<br>←<span>架构反馈与客户需求</span></div><div class="party partner-party"><small>合作伙伴与方案提供商</small><strong>博思云为</strong><p>负责评估、架构、服务选型、IaC 实施、安全运营、项目治理和持续优化。</p></div><div class="party-link"><span>交付方案与运营服务</span>→<br>←<span>业务需求、授权与验收</span></div><div class="party customer-party"><small>SMB 客户与落地对象</small><strong>福驾科技</strong><p>提供业务目标与账户授权，参与风险决策、变更审批、事件协同和最终验收。</p></div></div>
${section('博思云为交付生命周期','从售前发现到持续运营的端到端责任')}<div class="partner-lifecycle">${lifecycle.map(x=>`<article><b>${x[0]}</b><div><strong>${x[1]}</strong><p>${x[2]}</p></div></article>`).join('')}</div>
${section('项目 RACI','A=最终负责，R=执行，C=协作，I=知会')}<div class="card table-wrap"><table class="table"><thead><tr><th>活动</th><th>AWS</th><th>博思云为</th><th>福驾科技</th><th>主要产出</th></tr></thead><tbody>${[
 ['业务需求与风险优先级','I','C','A/R','需求与风险清单'],['AWS 服务选型与目标架构','C','A/R','C','架构图与设计决策'],['账户授权与变更审批','I','C','A/R','跨账户角色与变更单'],['IaC 与安全服务实施','I','A/R','C','CloudFormation、Config、SCP'],['安全事件检测与响应','服务能力','A/R','C/A','事件时间线与处置报告'],['合规控制与自动采证','服务能力','A/R','C','控制映射与证据包'],['项目范围、进度和质量','I','A/R','C/A','SOW、里程碑、验收'],['持续优化与客户成功','C','A/R','C','月报、改进计划与路线图']
 ].map(r=>`<tr><td><b>${r[0]}</b></td><td>${tag('info',r[1])}</td><td>${tag('real',r[2])}</td><td>${tag('demo',r[3])}</td><td>${r[4]}</td></tr>`).join('')}</tbody></table></div>
${section('博思云为在本项目中的具体产出','这些交付物把 AWS 产品变成可落地方案')}<div class="grid grid-4">${[['架构与治理','多账户架构、IAM 权限模型、网络和日志设计'],['自动化资产','CloudFormation、40 条 Config 规则、10 条 SCP、Lambda Runbook'],['安全运营','Finding 分级、8 类事件手册、自动响应与通知'],['交付治理','评估、SOW、RACI、M0–M5、培训、验收和报告']].map(x=>`<article class="card"><div class="partner-icon">BY</div><h3>${x[0]}</h3><p class="small muted">${x[1]}</p></article>`).join('')}</div>`;}
function awsSolution(){const services=[
 ['治理与身份','AWS Organizations','统一管理多账户，并用 SCP 阻止高风险操作','预防'],['治理与身份','AWS IAM Identity Center','集中登录、MFA 和基于岗位的权限集','预防'],['身份权限','AWS IAM','最小权限角色、跨账户 AssumeRole 与凭证生命周期','预防'],['审计追踪','AWS CloudTrail','记录所有 API 活动，支撑调查和不可抵赖审计','可见'],['配置合规','AWS Config','持续记录资源配置并通过 40 条规则发现偏差','检测'],['态势聚合','AWS Security Hub','聚合 FSBP/CIS 控制与多账户安全发现','检测'],['威胁检测','Amazon GuardDuty','分析 CloudTrail、VPC Flow Logs 和 DNS 等信号识别威胁','检测'],['漏洞管理','Amazon Inspector','持续扫描 EC2、ECR 与 Lambda 软件漏洞','检测'],['补丁管理','AWS Systems Manager Patch Manager','按补丁基线和维护窗口自动化修补','响应'],['数据保护','AWS KMS','使用客户托管密钥控制 S3、EBS、RDS 与日志加密','保护'],['数据发现','Amazon Macie','发现并分类 S3 中的个人、财务等敏感数据','保护'],['事件编排','Amazon EventBridge','把高危 Finding 实时路由到响应工作流','响应'],['自动处置','AWS Lambda','执行隔离实例、禁用密钥、阻断 S3 公开访问等 Runbook','响应'],['通知协同','Amazon SNS','向客户负责人和安全团队发送处置通知','响应'],['持续审计','AWS Audit Manager','将控制映射到自动采集的 AWS 证据并生成评估','审计'],['证据存储','Amazon S3 Object Lock','配合 KMS 保存不可篡改的日志和审计证据','审计']
 ];return `<div class="aws-hero"><div><span>BUILT ON AWS</span><h2>AWS 原生安全服务是方案的执行引擎</h2><p>博思云为不是替代 AWS，而是把分散的 AWS 安全服务编排成适合中小企业的标准产品。AWS 负责多账户治理、遥测、威胁检测、加密、自动响应和证据采集；博思云为负责评估、架构、配置、自动化交付与持续运营；福驾科技作为客户负责需求、授权、风险决策和验收。</p></div><div class="aws-outcome"><small>客户业务结果</small><strong>61% → 82%</strong><span>当前 Security Hub 安全评分</span></div></div>
${section('AWS 在方案中的端到端作用','从预防到检测、响应和审计形成闭环')}
<div class="aws-flow"><div class="aws-stage prevent"><b>① 预防</b><strong>Organizations · IAM Identity Center</strong><span>SCP、MFA、RBAC 在风险发生前建立护栏</span></div><i>→</i><div class="aws-stage detect"><b>② 检测</b><strong>Security Hub · GuardDuty · Config</strong><span>持续发现威胁、配置偏差和漏洞</span></div><i>→</i><div class="aws-stage respond"><b>③ 响应</b><strong>EventBridge · Lambda · SNS</strong><span>事件驱动隔离、遏制和通知</span></div><i>→</i><div class="aws-stage protect"><b>④ 保护</b><strong>KMS · Macie · S3</strong><span>加密数据并发现敏感信息</span></div><i>→</i><div class="aws-stage audit"><b>⑤ 审计</b><strong>Audit Manager · CloudTrail</strong><span>自动采证、追踪和持续改进</span></div></div>
${section('客户问题 → AWS 服务 → 业务价值','每项产品能力都有明确 AWS 技术落点')}
<div class="grid grid-3"><article class="card aws-value"><span class="tag tag-gap">问题</span><h3>账户分散、权限过大</h3><p>AWS Organizations + IAM Identity Center + SCP</p><b>统一入口并实施组织级最小权限</b></article><article class="card aws-value"><span class="tag tag-gap">问题</span><h3>不知道资源是否安全</h3><p>Security Hub + Config + Inspector</p><b>把安全状态变成持续可量化指标</b></article><article class="card aws-value"><span class="tag tag-gap">问题</span><h3>高危事件响应太慢</h3><p>GuardDuty + EventBridge + Lambda + SNS</p><b>分钟级检测缩短为秒级响应编排</b></article><article class="card aws-value"><span class="tag tag-gap">问题</span><h3>敏感数据缺少保护</h3><p>KMS + Macie + S3 Block Public Access</p><b>加密、分类并阻断公开暴露</b></article><article class="card aws-value"><span class="tag tag-gap">问题</span><h3>审计依赖人工截图</h3><p>Config + Audit Manager + S3 Object Lock</p><b>持续评估并自动沉淀不可篡改证据</b></article><article class="card aws-value"><span class="tag tag-info">博思云为作用</span><h3>AWS 服务难以组合落地</h3><p>标准架构 + IaC + Runbook + 托管运营</p><b>以 80% 标准化组件降低 SMB 使用门槛</b></article></div>
${section('AWS 服务清单与责任','清楚说明每个服务在方案中做什么')}<div class="card table-wrap"><table class="table"><thead><tr><th>能力域</th><th>AWS 服务</th><th>在解决方案中的作用</th><th>阶段</th></tr></thead><tbody>${services.map(s=>`<tr><td>${s[0]}</td><td><b>${s[1]}</b></td><td>${s[2]}</td><td>${tag(s[3]==='响应'?'gap':s[3]==='检测'?'demo':'info',s[3])}</td></tr>`).join('')}</tbody></table></div>`;}
function cloudTelemetryPanel(kind){if(!state.awsConnected)return `<div class="cloud-mode-note"><div><b>当前使用本地可执行适配器</b><span>连接部署后的 Cognito 和 API Gateway 后，此区域显示 AWS API 实时数据。</span></div><button class="button button-ghost" id="inlineAwsConnect">连接 AWS</button></div>`;const c=state.cloud||{},data=c[kind];if(!data||data.error)return `<div class="alert alert-danger">AWS实时数据读取失败：${esc(data?.error||'尚未同步')}</div>`;if(kind==='topology')return `<div class="cloud-live"><span class="live-pulse"></span><b>AWS CloudFormation 实时拓扑</b><span>${data.stackResources?.length||0} 个栈资源</span><span>${esc(data.region)}</span><span>${fmt(data.observedAt)}</span></div>`;if(kind==='resources')return `<div class="cloud-live"><span class="live-pulse"></span><b>AWS 资源实时清单</b><span>${data.total||0} 个标签资源</span><span>${data.activeAlarms?.length||0} 个CloudWatch告警</span><span>$${data.monthlyCostUsd||0}/月</span><span>${fmt(data.observedAt)}</span></div>`;if(kind==='protection')return `<div class="cloud-live"><span class="live-pulse"></span><b>KMS / S3 / Macie 实时扫描</b><span>${data.kmsKeys?.length||0} 个KMS密钥</span><span>${data.buckets?.length||0} 个Bucket</span><span>${data.macieFindings?.length||0} 个Macie发现</span><span>${fmt(data.observedAt)}</span></div>`;if(kind==='evidence')return `<div class="cloud-live"><span class="live-pulse"></span><b>S3 Object Lock证据库</b><span>${data.items?.length||0} 份云端证据</span><span>SHA-256验证</span></div>`;return ''}
function resourcesPage(){const rs=state.data.cloudResources,total=rs.reduce((n,r)=>n+r.monthlyCostUsd,0),warnings=rs.filter(r=>r.health==='warning');return `${section('福驾科技云资源中心','业务工作负载、健康监控、加密状态和月度成本统一视图','<button class="button button-primary" id="checkResources">↻ 执行健康检查</button>')}${cloudTelemetryPanel('resources')}<div class="grid grid-4">${metric('受管资源',rs.length,'覆盖3个AWS账户')}${metric('健康资源',rs.filter(r=>r.health==='healthy').length,`${warnings.length} 个资源需要关注`,'#e5f8f1')}${metric('加密覆盖',`${Math.round(rs.filter(r=>r.encryption).length/rs.length*100)}%`,'KMS与服务端加密')}${metric('月度成本',`$${total.toLocaleString()}`,'Cost Explorer估算','#fff3dc')}</div>${section('业务架构资源','系统图中的计算、数据库、缓存和存储均映射为可监控资源')}<div class="resource-cards">${rs.map(r=>`<article class="resource-card ${r.health}"><div class="flex between"><span class="resource-service">${esc(r.service)}</span>${tag(r.health==='healthy'?'real':'demo',r.health==='healthy'?'正常':'告警')}</div><h3>${esc(r.name)}</h3><code>${esc(r.resourceId)}</code><p>${esc(r.purpose)}</p><div class="resource-meta"><span>账户<b>${esc(r.accountId)}</b></span><span>区域<b>${esc(r.region)}</b></span><span>加密<b>${esc(r.encryption)}</b></span><span>成本<b>$${r.monthlyCostUsd}/月</b></span></div><small>${esc(r.monitoring)} · 检查于 ${fmt(r.lastCheckedAt)}</small></article>`).join('')}</div>${warnings.length?`<div class="alert alert-warning" style="margin-top:14px"><b>需要关注：</b>${warnings.map(r=>`${r.name}（${r.monitoring}）`).join('、')}。可前往安全发现或数据保护页面继续处理。</div>`:''}`;}
function protectionPage(){const dp=state.data.dataProtection,s=dp.summary;return `${section('数据保护中心','KMS密钥、Macie敏感数据和业务存储加密状态','<button class="button button-primary" id="runProtectionScan">运行数据保护扫描</button>')}${cloudTelemetryPanel('protection')}<div class="grid grid-4">${metric('加密覆盖',`${s.encryptionCoverage}%`,'S3 · EBS · RDS · DocumentDB')}${metric('KMS CMK',s.kmsKeys,`${s.rotatingKeys} 个启用自动轮换`,'#e5f8f1')}${metric('Macie发现',s.macieFindings,'敏感数据待复核','#fff3dc')}${metric('公开Bucket',s.publicBuckets,'需阻断公共访问','#ffe7e7')}</div>${section('保护链路','从密钥管理到敏感数据发现与证据归档')}<div class="protection-flow"><button data-arch-action="rotate_keys"><b>AWS KMS</b><span>密钥轮换检查</span></button><i>→</i><button data-page-link="resources"><b>业务存储</b><span>S3 / EBS / RDS</span></button><i>→</i><button data-arch-action="collect_evidence"><b>Amazon Macie</b><span>敏感数据扫描</span></button><i>→</i><button data-page-link="evidence"><b>证据中心</b><span>哈希与归档</span></button></div>${section('受保护资产',`最近扫描 ${fmt(s.lastScanAt)}`)}<div class="card table-wrap"><table class="table"><thead><tr><th>资产</th><th>服务</th><th>账户 / 区域</th><th>加密方式</th><th>健康</th><th>用途</th></tr></thead><tbody>${dp.assets.map(r=>`<tr><td><b>${esc(r.name)}</b><br><code>${esc(r.resourceId)}</code></td><td>${esc(r.service)}</td><td>${esc(r.accountId)}<br>${esc(r.region)}</td><td>${tag('real',r.encryption)}</td><td>${tag(r.health==='healthy'?'real':'demo',r.health)}</td><td>${esc(r.purpose)}</td></tr>`).join('')}</tbody></table></div><div class="grid grid-2" style="margin-top:16px"><article class="card"><h3>KMS密钥治理</h3><div class="matrix"><div class="matrix-item">客户托管密钥<b>6</b></div><div class="matrix-item">自动轮换<b>100%</b></div><div class="matrix-item">待删除密钥<b>0</b></div><div class="matrix-item">跨账户授权<b>3</b></div></div><button class="button button-ghost arch-action" data-arch-action="rotate_keys" style="margin-top:12px">执行密钥治理检查</button></article><article class="card"><h3>Macie敏感数据</h3><p class="small">在 <code>fj-customer-exports</code> 检测到财务与个人数据分类结果，当前进入人工复核。</p><div class="alert alert-warning">1 个 Finding · Medium · 建议检查存储保留和访问策略</div><button class="button button-ghost" data-page-link="findings" style="margin-top:12px">查看安全发现</button></article></div>`;}
function evidencePage(){const cloudItems=state.cloud?.evidence?.items,items=state.awsConnected&&Array.isArray(cloudItems)?cloudItems:state.data.evidenceArtifacts;return `${section('安全证据中心','集中管理Agent、Config、Security Hub、GuardDuty和CloudTrail证据','<button class="button button-primary" data-arch-action="collect_evidence">采集新证据</button>')}${cloudTelemetryPanel('evidence')}<div class="grid grid-4">${metric('证据总数',items.length,'Agent自动采集')}${metric('来源服务',new Set(items.flatMap(x=>x.sources||[])).size,'Config · Security Hub · GuardDuty · CloudTrail')}${metric('已验证',items.filter(x=>x.integrityValid).length,'SHA-256完整性')}${metric('待验证',items.filter(x=>!x.integrityValid).length,'点击执行完整性检查','#fff3dc')}</div>${section('证据归档','每份证据包含来源、采集人、时间和完整性哈希')}<div class="grid grid-2">${items.map(x=>`<article class="card evidence-card"><div class="flex between"><div>${tag('info',x.type)}</div>${x.integrityValid?tag('real','完整性有效'):tag('demo','待验证')}</div><h3>${esc(x.name)}</h3><p class="small muted">${(x.sources||[]).map(esc).join(' · ')}</p><div class="hash-box"><span>SHA-256</span><code>${esc(x.hash)}</code></div><p class="small">采集：${esc(x.collectedBy)} · ${fmt(x.createdAt)}</p>${x.verifiedAt?`<p class="small good">已由 ${esc(x.verifiedBy)} 于 ${fmt(x.verifiedAt)} 验证</p>`:`<button class="button button-dark verify-evidence" data-id="${x.id}">验证证据完整性</button>`}</article>`).join('')}</div>`;}
function copilotPage(){const ai=state.data.aiInsights;return `<div class="copilot-hero"><div><span>✦ CLOUDGUARD INTELLIGENCE</span><h2>从告警数据到可执行决策</h2><p>联合分析安全发现、事件、合规控制和交付项目，识别关联信号、解释风险来源，并给出按优先级排序的建议。所有建议均需人工复核后执行。</p><small>${ai.engine.mode==='local-explainable'?'可解释本地智能引擎':'托管模型'} · ${fmt(ai.generatedAt)}</small></div><div class="risk-orb level-${ai.riskLevel==='高'?'high':ai.riskLevel==='中'?'medium':'low'}"><strong>${ai.riskScore}</strong><span>风险分数</span><small>${ai.riskLevel}风险</small></div></div>
<div class="grid grid-3" style="margin-top:16px">${metric('安全发现贡献',ai.factors.findings+' 分','按严重度和开放状态计算','#ffe7e7')}${metric('控制缺口贡献',ai.factors.controls+' 分','不合规与例外控制','#fff3dc')}${metric('开放事件贡献',ai.factors.incidents+' 分','按事件严重度计算','#e8f2ff')}</div>
${section('主动洞察','引擎自动发现需要关注的运营变化')}<div class="grid grid-2">${ai.insights.map(x=>`<article class="card insight-card ${x.level}"><div class="flex between"><span class="ai-label">AI INSIGHT</span>${tag(x.level==='critical'?'gap':x.level==='high'?'demo':'info',x.level.toUpperCase())}</div><h3>${esc(x.title)}</h3><p>${esc(x.detail)}</p><b>建议：${esc(x.action)}</b></article>`).join('')}</div>
${section('关联信号','跨来源、跨资源识别共同根因')}<div class="card">${ai.correlations.length?ai.correlations.map(c=>`<div class="correlation"><div class="correlation-count">${c.count}</div><div><b>账户 ${esc(c.accountId)}</b><p>${esc(c.explanation)}</p><div class="service-chips">${c.sources.map(s=>`<span>${esc(s)}</span>`).join('')}</div></div><span class="severity ${c.severity>=8?'critical':'high'}">${c.severity}</span></div>`).join(''):'<div class="empty-state"><strong>未发现关联信号</strong>当前没有同一账户的多来源开放 Finding。</div>'}</div>
${section('优先处置队列','综合严重度、状态和影响资源排序')}<div class="card table-wrap"><table class="table"><thead><tr><th>优先级</th><th>风险摘要</th><th>分类</th><th>置信度</th><th>首要建议</th></tr></thead><tbody>${ai.priorities.map(p=>`<tr><td>${tag(p.priority==='P0'?'gap':'demo',p.priority)}</td><td>${esc(p.summary)}</td><td>${esc(p.category)}</td><td><b>${p.confidence}%</b></td><td>${esc(p.actions[0])}</td></tr>`).join('')}</tbody></table></div>
${section('询问运营数据','自然语言查询使用当前租户实时数据，不编造缺失信息')}<div class="copilot-chat"><div id="chatMessages"><div class="chat-message assistant"><b>智能助手</b><p>你可以问我：当前最大风险是什么？有哪些合规缺口？项目进展如何？</p></div></div><div class="prompt-chips"><button data-question="当前最大风险是什么？">当前最大风险</button><button data-question="有哪些合规缺口？">合规缺口</button><button data-question="安全事件状态如何？">事件状态</button><button data-question="项目进度怎么样？">项目进度</button></div><form id="copilotForm"><input name="question" placeholder="询问当前安全运营数据..." required><button class="button ai-button" type="submit">发送</button></form></div>
<div class="alert alert-info" style="margin-top:16px"><b>可信 AI 边界：</b>${esc(ai.engine.disclaimer)} 生产环境可接入 Amazon Bedrock 生成更丰富的摘要，但风险分数、证据引用和执行审批仍由确定性控制保证。</div>`;}
function customers(){return `${section('客户接入','采集企业画像、联系人与 SMB 资格信息','<button class="button button-primary" id="newCustomer">+ 新建客户</button>')}<div class="page-note">SMB 资格仅按年收入 &lt; USD 100M 做系统初筛，最终资格还需排除 Startup、ISV 和 Digital Native Business，并由人工复核。</div><div class="card table-wrap"><table class="table"><thead><tr><th>客户</th><th>行业</th><th>员工</th><th>年收入 USD</th><th>SMB 初筛</th><th>AWS 接入</th><th>联系人</th><th>接入时间</th></tr></thead><tbody>${state.data.customers.length?state.data.customers.map(c=>`<tr><td><b>${esc(c.name)}</b></td><td>${esc(c.industry)}</td><td>${c.employeeCount}</td><td>$${Number(c.annualRevenueUsd).toLocaleString()}</td><td>${c.isSmb?tag('real','通过'):tag('gap','不符合')}</td><td>${c.awsConnection?.status==='connected'?`${tag('real','已连接')}<br><span class="muted">${c.awsConnection.accountCount} 账户 · ${fmt(c.awsConnection.lastSyncAt)}</span>`:tag('demo','待接入')}</td><td>${esc(c.contactName)}<br><span class="muted">${esc(c.contactEmail)}</span></td><td>${fmt(c.createdAt)}</td></tr>`).join(''):`<tr><td colspan="8"><div class="empty-state"><strong>尚未接入客户</strong>创建第一个真实客户档案开始交付流程。</div></td></tr>`}</tbody></table></div>`;}
function catalog(){const opts=state.data.customers.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('');return `${section('标准化安全服务','固定范围、价格和平均交付周期')}<div class="grid grid-4">${Object.entries(state.config.offerings).map(([name,o])=>`<article class="card"><span class="tag tag-info">${esc(o.solutionArea)}</span><h2>${name}</h2><div class="metric-value">¥${o.price.toLocaleString()}</div><p class="small muted">${o.durationDays} 天标准交付</p><ul class="check-list">${o.capabilities.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="aws-role"><b>技术实现</b><span>${esc(o.awsRole)}</span></div><div class="service-chips">${o.awsServices.slice(0,5).map(x=>`<span>${esc(x.replace('Amazon ','').replace('AWS ',''))}</span>`).join('')}${o.awsServices.length>5?`<span>+${o.awsServices.length-5}</span>`:''}</div><button class="button button-primary buy" data-offer="${name}" ${!opts?'disabled':''}>选择产品</button></article>`).join('')}</div>${!opts?'<div class="alert alert-warning" style="margin-top:16px">请先创建客户，再进行安全评估与采购。</div>':''}`;}
function projects(){return `${section('交付项目','M0 启动 → M1 评估 → M2 设计 → M3 部署 → M4 整改演练 → M5 验收')}<div class="grid grid-2">${state.data.projects.length?state.data.projects.map(p=>`<article class="card"><div class="flex between"><div><span class="tag tag-info">${esc(p.offering)}</span><h3>${esc(p.name)}</h3></div><b>${p.progress}%</b></div>${progress(p.progress,'green')}<p class="small muted">负责人 ${esc(p.owner)} · 当前 ${p.currentMilestone}</p><div class="milestones">${p.milestones.map(m=>`<button class="milestone ${m.status}" data-project="${p.id}" data-milestone="${m.code}"><b>${m.code}</b><small>${m.status==='accepted'?'已验收':m.status==='in_progress'?'进行中':'待开始'}</small></button>`).join('')}</div>${p.deliveryTeam?`<div class="delivery-team"><div class="flex between"><b>托管交付团队 · ${esc(p.deliveryProvider)}</b>${tag('info','服务中')}</div>${p.deliveryTeam.map(x=>`<div><span class="partner-icon small-icon">BY</span><span><b>${esc(x.role)}</b><small>${esc(x.responsibility)}</small></span></div>`).join('')}</div>`:''}${p.awsDeployment?`<div class="aws-deployment"><div class="flex between"><b>AWS 服务部署状态</b><span class="small muted">${p.awsDeployment.filter(x=>x.status==='active').length}/${p.awsDeployment.length} 已启用</span></div>${p.awsDeployment.map(x=>`<div><span><b>${esc(x.service)}</b><small>${esc(x.role)}</small></span>${tag(x.status==='active'?'real':x.status==='deploying'?'demo':'neutral',x.status==='active'?'已启用':x.status==='deploying'?'部署中':'计划中')}</div>`).join('')}</div>`:''}</article>`).join(''):`<div class="card empty-state"><strong>暂无项目</strong>在产品采购页面确认订单后，系统将自动创建标准交付项目。</div>`}</div>`;}
function findings(){return `${section('安全发现','接收 Security Hub / GuardDuty / Config / Macie 数据或人工录入','<button class="button button-primary" id="newFinding">+ 录入 Finding</button>')}<div class="page-note">生产集成使用 <code>POST /api/integrations/aws/findings</code> 与 <code>X-Webhook-Secret</code>。平台保留来源、账户、区域、资源和严重级别。</div><div class="card table-wrap"><table class="table"><thead><tr><th>类型</th><th>来源</th><th>严重度</th><th>AWS 账户/区域</th><th>资源</th><th>状态</th><th></th></tr></thead><tbody>${state.data.findings.length?state.data.findings.slice().reverse().map(f=>`<tr><td><b>${esc(f.type)}</b><br><span class="muted">${fmt(f.createdAt)}</span></td><td>${esc(f.source)}</td><td class="${f.severity>=8?'critical':f.severity>=7?'high':f.severity>=4?'medium':'low'}"><b>${f.severity}</b></td><td>${esc(f.accountId)}<br>${esc(f.region)}</td><td>${esc(f.resourceId)}</td><td>${tag(f.status==='open'?'gap':'info',f.status)}</td><td><div class="toolbar"><button class="button ai-button analyze-finding" data-id="${f.id}">✦ 智能分析</button>${f.status==='open'?`<button class="button button-dark make-incident" data-id="${f.id}">创建事件</button>`:''}</div></td></tr>`).join(''):`<tr><td colspan="7"><div class="empty-state"><strong>暂无 Finding</strong>接入 AWS 安全服务或录入已确认的安全发现。</div></td></tr>`}</tbody></table></div>`;}
function incidents(){return `${section('事件响应','按检测、分级、遏制、取证、通知和复盘留痕')}<div class="page-note">Security Hub 和 GuardDuty 的高危发现通过 EventBridge 进入响应队列。系统在未配置受控执行角色时不直接修改云资源；托管服务工程师先执行 DRY_RUN，再根据审批结果完成处置并记录说明。</div><div class="grid grid-2">${state.data.incidents.length?state.data.incidents.slice().reverse().map(i=>`<article class="card ${i.severity==='critical'?'danger-zone':''}"><div class="flex between"><span class="severity ${i.severity}">${i.severity.toUpperCase()}</span>${tag(i.status==='resolved'?'real':'info',i.status)}</div><h3>${esc(i.title)}</h3><p class="small muted">${i.id} · ${fmt(i.createdAt)}</p><div class="timeline">${i.plan.map(s=>`<div class="timeline-item"><div class="flex between"><strong>${esc(s.name)}</strong>${tag(s.status==='completed'?'real':s.status==='validated'?'demo':'neutral',s.status)}</div>${s.status!=='completed'?`<div class="toolbar" style="margin-top:6px"><button class="button button-ghost incident-action" data-id="${i.id}" data-step="${s.index}" data-mode="dry_run">验证计划</button><button class="button button-dark incident-action" data-id="${i.id}" data-step="${s.index}" data-mode="manual_confirmed">确认已执行</button></div>`:''}</div>`).join('')}</div></article>`).join(''):`<div class="card empty-state"><strong>暂无安全事件</strong>从开放 Finding 创建事件并执行响应流程。</div>`}</div>`;}
function identity(){return `${section('身份与访问治理','集中身份、MFA、最小权限和定期访问复核','<button class="button button-primary" id="newReview">+ 记录访问复核</button>')}<div class="grid grid-4">${metric('推荐权限集','5','Admin · Developer · Operations · ReadOnly · Audit')}${metric('MFA 基线','Required','所有人机交互身份')}${metric('SCP 护栏','10','Root OU 与 Production OU')}${metric('复核周期','90 天','高权限账户每月复核')}</div>${section('组织安全护栏','策略代码位于 SEC-002/scp-policies')}<div class="grid grid-2">${['关键操作必须 MFA','禁止 Root Access Key','禁止 Root 日常操作','限制获批区域','禁止离开 Organization','强制 S3 加密','强制 EBS 加密','强制 RDS 加密','禁止 S3 公开访问','禁止停用安全服务'].map((x,i)=>`<div class="card flat flex between"><span>${String(i+1).padStart(2,'0')} · ${x}</span>${tag('real','策略文件')}</div>`).join('')}</div>`;}
function compliance(){const cm=state.data.configMonitoring,cs=state.data.controls,filter=state.configFilter,services=[...new Set(cm.rules.map(r=>r.service))];const visible=cm.rules.filter(r=>(filter.status==='all'||r.status===filter.status)&&(filter.service==='all'||r.service===filter.service)&&(!filter.query||`${r.code} ${r.name} ${r.service}`.toLowerCase().includes(filter.query.toLowerCase())));return `${section('AWS Config 合规监控中心','跨账户、跨区域持续记录配置变更并评估40条安全规则','<button class="button button-primary" id="runConfigEvaluation">↻ 立即重新评估</button>')}
<div class="monitor-status"><span class="live-pulse"></span><b>持续监控运行中</b><span>3 个 Configuration Recorder</span><span>最后评估 ${fmt(cm.summary.lastEvaluationAt)}</span><span>下次计划 ${fmt(cm.summary.nextEvaluationAt)}</span></div>
<div class="grid grid-4">${metric('资源合规率',cm.summary.score===null?'未评估':`${cm.summary.score}%`,`${cm.summary.compliantResources}/${cm.summary.totalResources} 个资源合规`)}${metric('规则状态',`${cm.summary.compliantRules}/${cm.summary.totalRules}`,`${cm.summary.nonCompliantRules} 条规则不合规`,'#e5f8f1')}${metric('不合规资源',cm.summary.nonCompliantResources,`${cm.summary.unknownResources} 个资源状态未知`,'#ffe7e7')}${metric('自动整改规则',cm.summary.autoRemediation,`${cm.rules.filter(r=>r.remediationStatus==='queued').length} 个整改任务排队中`,'#fff3dc')}</div>
${section('合规趋势','最近28天 Config 资源合规率变化')}<article class="card config-trend-card">${configTrendChart(cm.snapshots)}<div class="trend-summary"><div><span>起始</span><b>${cm.snapshots[0]?.score??'—'}%</b></div><div><span>当前</span><b>${cm.summary.score??'—'}%</b></div><div><span>净提升</span><b class="good">+${(cm.summary.score||0)-(cm.snapshots[0]?.score||0)}%</b></div><div><span>评估频率</span><b>每 6 小时</b></div></div></article>
<div class="grid grid-2">${section('账户合规分布','三个已接入 AWS 账户')}<span></span></div><div class="grid grid-2"><article class="card"><h3 style="margin-top:0">按账户</h3>${cm.accountBreakdown.map(a=>`<div class="breakdown-row"><div><b>${esc(a.name)}</b><small>${esc(a.accountId)} · ${a.total} 资源</small></div>${progress(a.score,a.score>=85?'green':'orange')}<strong>${a.score}%</strong></div>`).join('')}</article><article class="card"><h3 style="margin-top:0">按服务</h3>${cm.serviceBreakdown.map(s=>`<div class="breakdown-row"><div><b>${esc(s.service)}</b><small>${s.nonCompliant} 项不合规</small></div>${progress(s.score,s.score>=85?'green':'orange')}<strong>${s.score}%</strong></div>`).join('')}</article></div>
${section('Config 规则监控',`显示 ${visible.length} / ${cm.rules.length} 条规则 · 支持筛选与资源钻取`)}<div class="card"><div class="config-toolbar"><input id="configSearch" value="${esc(filter.query)}" placeholder="搜索规则名称或代码"><select id="configStatus"><option value="all">全部状态</option><option value="compliant">合规</option><option value="non_compliant">不合规</option></select><select id="configService"><option value="all">全部服务</option>${services.map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('')}</select></div><div class="table-wrap"><table class="table"><thead><tr><th>规则</th><th>AWS 服务</th><th>模式</th><th>资源评估</th><th>状态</th><th>最近评估</th><th></th></tr></thead><tbody>${visible.map(r=>`<tr><td><b>${esc(r.name)}</b><br><code>${esc(r.code)}</code></td><td>${esc(r.service)}</td><td>${tag('neutral',r.evaluationMode==='periodic'?'周期':'配置变更')}</td><td><span class="good">${r.compliantResources} 合规</span>${r.nonCompliantResources?` · <span class="critical">${r.nonCompliantResources} 不合规</span>`:''}</td><td>${tag(r.status==='compliant'?'real':'gap',r.status==='compliant'?'合规':'不合规')}</td><td>${fmt(r.lastEvaluatedAt)}</td><td><button class="button button-ghost config-detail" data-id="${r.id}">查看</button></td></tr>`).join('')}</tbody></table></div></div>
${section('不合规资源整改队列','从规则发现直接进入调查和自动化整改')}<div class="card table-wrap"><table class="table"><thead><tr><th>资源</th><th>规则</th><th>账户 / 区域</th><th>严重度</th><th>整改建议</th><th>状态</th><th></th></tr></thead><tbody>${cm.nonCompliantResources.map(x=>`<tr><td><b>${esc(x.resourceId)}</b><br><span class="muted">${esc(x.resourceType)}</span></td><td>${esc(x.ruleName)}</td><td>${esc(x.accountId)}<br>${esc(x.region)}</td><td class="severity ${x.severity}">${esc(x.severity).toUpperCase()}</td><td>${esc(x.remediation)}</td><td>${tag(x.remediationStatus==='queued'?'demo':x.remediationStatus==='available'?'info':'neutral',x.remediationStatus==='queued'?'排队中':x.remediationStatus==='available'?'可自动整改':'待处理')}</td><td>${x.remediationStatus!=='queued'?`<button class="button button-dark remediate-config" data-id="${x.ruleId}">发起整改</button>`:'—'}</td></tr>`).join('')}</tbody></table></div>
${section('配置变更时间线','Config 检测到的关键资源配置变化')}<div class="card"><div class="config-timeline">${cm.changes.map(c=>`<div class="config-change"><span class="change-icon ${c.severity}"></span><div><div class="flex between"><b>${esc(c.change)}</b>${tag(c.severity==='resolved'?'real':c.severity==='critical'?'gap':'demo',c.severity==='resolved'?'已恢复':c.severity.toUpperCase())}</div><p>${esc(c.resourceType)} · ${esc(c.resourceId)}</p><small>${esc(c.accountId)} / ${esc(c.region)} · ${fmt(c.detectedAt)} · 规则 ${esc(c.ruleCode)}</small></div></div>`).join('')}</div></div>
${section('治理控制与证据','Config 监控结果与框架控制关联')}<div class="card table-wrap"><table class="table"><thead><tr><th>框架</th><th>控制</th><th>要求</th><th>状态</th><th>证据引用</th><th></th></tr></thead><tbody>${cs.map(c=>`<tr><td>${esc(c.framework)}</td><td><b>${esc(c.code)}</b></td><td>${esc(c.title)}</td><td>${tag(c.status==='compliant'?'real':c.status==='non_compliant'?'gap':c.status==='exception'?'demo':'neutral',c.status)}</td><td>${esc(c.evidenceRef||'—')}</td><td><button class="button button-ghost assess-control" data-id="${c.id}">评估</button></td></tr>`).join('')}</tbody></table></div>`;}
function reports(){return `${section('运营与合规报告','基于当前持久化业务数据生成，不填充模拟指标','<button class="button button-primary" id="newReport">生成报告</button>')}<div class="ai-report-note"><span class="ai-label">✦ 智能摘要</span><b>当前风险 ${state.data.aiInsights.riskScore}/100 · ${state.data.aiInsights.riskLevel}风险</b><p>${state.data.aiInsights.insights.map(x=>x.title).slice(0,3).join('；')}。生成报告时将使用当前业务快照，便于管理层快速决策。</p></div><div class="grid grid-2">${state.data.reports.length?state.data.reports.slice().reverse().map(r=>`<article class="card"><div class="flex between"><h3>${esc(r.type)}</h3>${tag('real','已生成')}</div><p class="small muted">${r.id} · ${fmt(r.createdAt)} · 托管服务团队签发</p><div class="matrix"><div class="matrix-item">已评估控制<b>${r.summary.assessed}</b></div><div class="matrix-item">合规控制<b>${r.summary.compliant}</b></div><div class="matrix-item">开放发现<b>${r.summary.openFindings}</b></div><div class="matrix-item">活跃项目<b>${r.summary.activeProjects}</b></div></div><button class="button button-ghost download-report" data-id="${r.id}" style="margin-top:12px">下载 JSON</button></article>`).join(''):`<div class="card empty-state"><strong>暂无报告</strong>报告只汇总当前真实录入/接入的数据。</div>`}</div>`;}
function audit(){return `${section('不可抵赖操作记录','登录、客户、采购、项目、安全处置、控制评估和报告生成均自动留痕')}<div class="card table-wrap"><table class="table"><thead><tr><th>时间</th><th>操作者</th><th>操作</th><th>对象</th><th>详情</th></tr></thead><tbody>${state.data.auditLogs.map(a=>`<tr><td>${fmt(a.createdAt)}</td><td>${esc(a.userEmail)}</td><td><b>${esc(a.action)}</b></td><td>${esc(a.entityType)}<br><span class="muted">${esc(a.entityId)}</span></td><td class="audit-detail" title="${esc(JSON.stringify(a.detail))}">${esc(JSON.stringify(a.detail))}</td></tr>`).join('')}</tbody></table></div>`;}
function bind(){
 document.querySelectorAll('.scenario-item').forEach(b=>b.onclick=()=>{state.agentScenario=b.dataset.scenario;render()});
 $('#runAgent')?.addEventListener('click',runGovernanceAgent);
 $('#inlineAwsConnect')?.addEventListener('click',startAwsLogin);
 document.querySelectorAll('[data-page-link]').forEach(b=>b.onclick=()=>navigate(b.dataset.pageLink));
 document.querySelectorAll('[data-arch-action]').forEach(b=>b.onclick=e=>{e.stopPropagation();executeArchitectureAction(b.dataset.archAction)});
 $('#checkResources')?.addEventListener('click',()=>mutate(()=>cloudApi('/resources/health-check',{method:'POST',body:'{}'}),'云资源健康检查完成'));
 $('#runProtectionScan')?.addEventListener('click',()=>mutate(()=>cloudApi('/data-protection/scan',{method:'POST',body:'{}'}),'数据保护扫描完成'));
 document.querySelectorAll('.verify-evidence').forEach(b=>b.onclick=()=>mutate(()=>cloudApi(`/evidence/${b.dataset.id}/verify`,{method:'POST',body:'{}'}),'证据完整性验证通过'));
 document.querySelectorAll('.analyze-finding').forEach(b=>b.onclick=()=>analyzeFinding(b.dataset.id));
 document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>askCopilot(b.dataset.question));
 const copilotForm=$('#copilotForm');if(copilotForm)copilotForm.onsubmit=e=>{e.preventDefault();const q=new FormData(e.target).get('question');askCopilot(q);e.target.reset()};
 const configStatus=$('#configStatus'),configService=$('#configService'),configSearch=$('#configSearch');if(configStatus){configStatus.value=state.configFilter.status;configService.value=state.configFilter.service;configStatus.onchange=()=>{state.configFilter.status=configStatus.value;render()};configService.onchange=()=>{state.configFilter.service=configService.value;render()};configSearch.onchange=()=>{state.configFilter.query=configSearch.value.trim();render()};configSearch.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();state.configFilter.query=configSearch.value.trim();render()}};}
 $('#runConfigEvaluation')?.addEventListener('click',()=>mutate(()=>api('/config-monitoring/evaluate',{method:'POST',body:'{}'}),'Config 评估已完成'));
 document.querySelectorAll('.config-detail').forEach(b=>b.onclick=()=>showConfigRule(b.dataset.id));
 document.querySelectorAll('.remediate-config').forEach(b=>b.onclick=()=>remediateConfig(b.dataset.id));
 $('#newCustomer')?.addEventListener('click',customerModal);document.querySelectorAll('.buy').forEach(b=>b.onclick=()=>procurementModal(b.dataset.offer));document.querySelectorAll('.milestone').forEach(b=>b.onclick=()=>milestoneModal(b.dataset.project,b.dataset.milestone));$('#newFinding')?.addEventListener('click',findingModal);document.querySelectorAll('.make-incident').forEach(b=>b.onclick=async()=>mutate(()=>api('/incidents',{method:'POST',body:JSON.stringify({findingId:b.dataset.id})}),'安全事件已创建','incidents'));document.querySelectorAll('.incident-action').forEach(b=>b.onclick=()=>incidentAction(b.dataset.id,b.dataset.step,b.dataset.mode));$('#newReview')?.addEventListener('click',identityModal);document.querySelectorAll('.assess-control').forEach(b=>b.onclick=()=>controlModal(b.dataset.id));$('#newReport')?.addEventListener('click',async()=>mutate(()=>api('/reports',{method:'POST',body:JSON.stringify({type:'security-governance'})}),'报告已生成'));document.querySelectorAll('.download-report').forEach(b=>b.onclick=()=>downloadReport(b.dataset.id));}
async function executeArchitectureAction(action){const labels={config_rules:'Config规则评估',rotate_keys:'身份与密钥治理',auto_remediate:'威胁自动整改',collect_evidence:'数据保护证据采集',generate_report:'合规报告生成'};toast(`正在执行 ${labels[action]||action}…`);try{if(state.awsConnected){const run=await cloudApi('/platform/actions',{method:'POST',body:JSON.stringify({action})});state.cloudLastRun=run;await loadCloud();toast(`${labels[action]}已由AWS云端执行 · ${run.engine||'aws-native'}`);render();return}const run=await api('/platform/actions',{method:'POST',body:JSON.stringify({action})});await load();state.page='agent';renderChrome();render();toast(`${labels[action]}完成 · ${run.steps.length}个工具步骤`)}catch(err){toast(err.message)}}
async function runGovernanceAgent(){const prompt=$('#agentPrompt')?.value||'';state.agentRunning=true;render();try{await new Promise(r=>setTimeout(r,700));if(state.awsConnected){const run=await cloudApi('/agent/runs',{method:'POST',body:JSON.stringify({scenario:state.agentScenario,prompt})});state.cloudLastRun=run;await loadCloud();toast('Agent 已通过AWS云端采集器执行');return}await api('/agent/runs',{method:'POST',body:JSON.stringify({scenario:state.agentScenario,prompt})});await load();state.page='agent';toast('Agent 已完成治理工具调用并生成报告')}catch(err){toast(err.message)}finally{state.agentRunning=false;render()}}
async function analyzeFinding(id){try{const a=await api(`/findings/${id}/analyze`,{method:'POST'});modal('智能分析结果',`<div class="analysis-result"><div class="flex between"><div>${tag(a.priority==='P0'?'gap':'demo',a.priority)} <b>${esc(a.category)}</b></div><span class="ai-confidence">置信度 ${a.confidence}%</span></div><h3>${esc(a.summary)}</h3><h4>建议响应步骤</h4><ol>${a.actions.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><h4>分析依据</h4><ul>${a.reasoning.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="alert alert-warning">建议由安全工程师复核后，通过事件响应流程执行。</div></div>`,'关闭',async()=>{});$('#modalForm').onsubmit=e=>{e.preventDefault();closeModal()};}catch(err){toast(err.message)}}
async function askCopilot(question){const box=$('#chatMessages');if(!box)return;box.innerHTML+=`<div class="chat-message user"><b>你</b><p>${esc(question)}</p></div><div class="chat-message assistant loading"><b>智能助手</b><p>正在联合分析运营数据...</p></div>`;box.scrollTop=box.scrollHeight;try{const r=await api('/ai/query',{method:'POST',body:JSON.stringify({question})});box.querySelector('.loading')?.remove();box.innerHTML+=`<div class="chat-message assistant"><b>智能助手</b><p>${esc(r.answer)}</p><small>依据：${r.sources.map(esc).join(' · ')}</small></div>`;box.scrollTop=box.scrollHeight}catch(err){box.querySelector('.loading p').textContent=err.message}}
function modal(title,body,submitText,onSubmit){$('#modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal"><h2>${title}</h2><form id="modalForm">${body}<div class="form-error" id="modalError"></div><div class="modal-actions"><button type="button" class="button button-ghost" id="modalClose">取消</button><button type="submit" class="button button-primary">${submitText}</button></div></form></div></div>`;$('#modalClose').onclick=closeModal;$('#modalForm').onsubmit=async e=>{e.preventDefault();try{await onSubmit(new FormData(e.target));closeModal()}catch(err){$('#modalError').textContent=err.message}};}
function closeModal(){$('#modalRoot').innerHTML='';}
function customerModal(){modal('新建客户',`<div class="form-grid"><div class="field"><label>企业名称</label><input name="name" required></div><div class="field"><label>行业</label><input name="industry" required></div><div class="field"><label>员工人数</label><input name="employeeCount" type="number" min="1" required></div><div class="field"><label>年收入（USD）</label><input name="annualRevenueUsd" type="number" min="0" required></div><div class="field"><label>联系人</label><input name="contactName" required></div><div class="field"><label>联系邮箱</label><input name="contactEmail" type="email" required></div></div>`,'创建客户',async fd=>{await mutate(()=>api('/customers',{method:'POST',body:JSON.stringify(Object.fromEntries(fd))}),'客户已创建')});}
function procurementModal(offering){const customers=state.data.customers.filter(c=>c.isSmb);modal(`采购 ${offering}`,`<div class="form-grid"><div class="field full"><label>客户</label><select name="customerId">${customers.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>AWS 账户数</label><input name="accountCount" type="number" min="1" value="1"></div><div class="field"><label>采购渠道</label><select name="purchaseChannel"><option value="direct">直接采购 / SOW</option><option value="marketplace">AWS Marketplace</option></select></div><div class="field full"><label><input type="checkbox" name="needsBaseline" checked> 安全基线</label>　<label><input type="checkbox" name="needsIdentity"> 身份治理</label>　<label><input type="checkbox" name="needsCompliance"> 合规审计</label></div></div><div class="alert alert-info">确认后将保存安全评估、生成真实订单记录并自动创建 M0–M5 项目。</div>`,'确认采购并创建项目',async fd=>{const o=Object.fromEntries(fd);const assessment=await api('/assessments',{method:'POST',body:JSON.stringify({customerId:o.customerId,accountCount:Number(o.accountCount),needsBaseline:fd.has('needsBaseline'),needsIdentity:fd.has('needsIdentity'),needsCompliance:fd.has('needsCompliance')})});await mutate(()=>api('/orders',{method:'POST',body:JSON.stringify({customerId:o.customerId,offering,purchaseChannel:o.purchaseChannel,assessmentId:assessment.id})}),'订单和交付项目已创建','projects')});}
function milestoneModal(projectId,code){modal(`更新里程碑 ${code}`,`<div class="field"><label>状态</label><select name="status"><option value="in_progress">进行中</option><option value="accepted">客户已验收</option><option value="pending">待开始</option></select></div><div class="alert alert-warning">选择“客户已验收”前，请确认真实验收记录已完成并归档。</div>`,'保存状态',async fd=>mutate(()=>api(`/projects/${projectId}/milestones/${code}`,{method:'PATCH',body:JSON.stringify(Object.fromEntries(fd))}),'里程碑已更新'));}
function findingModal(){modal('录入安全发现',`<div class="form-grid"><div class="field full"><label>Finding 类型</label><input name="type" placeholder="例如 Policy:S3/BucketAnonymousAccessGranted" required></div><div class="field"><label>来源</label><select name="source"><option>Security Hub</option><option>GuardDuty</option><option>AWS Config</option><option>Macie</option><option>manual</option></select></div><div class="field"><label>严重度（0–10）</label><input name="severity" type="number" min="0" max="10" step="0.1" required></div><div class="field"><label>AWS Account ID</label><input name="accountId" pattern="[0-9]{12}" required></div><div class="field"><label>区域</label><input name="region" value="cn-north-1" required></div><div class="field full"><label>资源 ID / ARN</label><input name="resourceId" required></div></div>`,'保存 Finding',async fd=>mutate(()=>api('/findings',{method:'POST',body:JSON.stringify(Object.fromEntries(fd))}),'Finding 已保存'));}
function incidentAction(id,step,mode){modal(mode==='dry_run'?'验证响应计划':'确认人工处置',`<div class="field"><label>执行说明</label><textarea name="note" required placeholder="记录验证结果、工单号、AWS 变更或证据位置"></textarea></div><input type="hidden" name="mode" value="${mode}">${mode==='manual_confirmed'?'<div class="alert alert-warning">此操作表示响应步骤已在真实环境完成，请勿虚假确认。</div>':''}`,'提交记录',async fd=>mutate(()=>api(`/incidents/${id}/actions/${step}`,{method:'POST',body:JSON.stringify(Object.fromEntries(fd))}),'响应记录已保存'));}
function identityModal(){modal('记录访问复核',`<div class="form-grid"><div class="field"><label>AWS Account ID</label><input name="accountId" pattern="[0-9]{12}" required></div><div class="field"><label>用户 / 角色 ARN</label><input name="principal" required></div><div class="field"><label>复核决定</label><select name="decision"><option value="retain">保留权限</option><option value="reduce">降低权限</option><option value="revoke">撤销权限</option></select></div><div class="field"><label>依据 / 工单</label><input name="evidenceRef" required></div></div>`,'保存复核',async fd=>mutate(()=>api('/identity-reviews',{method:'POST',body:JSON.stringify(Object.fromEntries(fd))}),'访问复核已记录'));}
function showConfigRule(id){const r=state.data.configMonitoring.rules.find(x=>x.id===id);if(!r)return;modal('Config 规则详情',`<div class="rule-detail-head"><div>${tag(r.status==='compliant'?'real':'gap',r.status==='compliant'?'合规':'不合规')} ${tag('neutral',r.severity.toUpperCase())}</div><h3>${esc(r.name)}</h3><code>${esc(r.code)}</code></div><div class="grid grid-2" style="margin-top:14px"><div class="matrix-item">合规资源<b>${r.compliantResources}</b></div><div class="matrix-item">不合规资源<b>${r.nonCompliantResources}</b></div></div><h4>评估配置</h4><p class="small">服务：${esc(r.service)}<br>触发方式：${r.evaluationMode==='periodic'?'周期评估':'配置变更触发'}<br>最近评估：${fmt(r.lastEvaluatedAt)}</p><h4>整改建议</h4><p class="small">${esc(r.remediation)}</p>${r.affectedResources.length?`<h4>受影响资源</h4><ul>${r.affectedResources.map(x=>`<li><code>${esc(x.resourceId)}</code> · ${esc(x.accountId)} / ${esc(x.region)}</li>`).join('')}</ul>`:''}`,'关闭',async()=>{});$('#modalForm').onsubmit=e=>{e.preventDefault();closeModal()};}
function remediateConfig(id){const r=state.data.configMonitoring.rules.find(x=>x.id===id);modal('发起 Config 整改',`<div class="alert alert-warning"><b>${esc(r.name)}</b><br>${esc(r.remediation)}</div><div class="field" style="margin-top:13px"><label>整改工单号</label><input name="ticket" value="CFG-${new Date().toISOString().slice(0,10).replaceAll('-','')}-${String(Date.now()).slice(-4)}" required></div><p class="small muted">提交后进入整改队列。自动化动作仍需通过受控执行角色和审批流程。</p>`,'加入整改队列',async fd=>mutate(()=>api(`/config-rules/${id}/remediate`,{method:'POST',body:JSON.stringify(Object.fromEntries(fd))}),'整改任务已加入队列'));}
function controlModal(id){modal('评估合规控制',`<div class="field"><label>评估状态</label><select name="status"><option value="compliant">合规</option><option value="non_compliant">不合规</option><option value="exception">已批准例外</option><option value="not_assessed">未评估</option></select></div><div class="field"><label>真实证据路径 / URL / 工单号</label><input name="evidenceRef" required></div>`,'保存评估',async fd=>mutate(()=>api(`/controls/${id}`,{method:'PATCH',body:JSON.stringify(Object.fromEntries(fd))}),'控制评估已保存'));}
async function mutate(fn,message,next){await fn();await load();toast(message);if(next)navigate(next);}
function downloadReport(id){const r=state.data.reports.find(x=>x.id===id),blob=new Blob([JSON.stringify(r,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${id}.json`;a.click();URL.revokeObjectURL(a.href);}
function toast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2500);}
function base64url(bytes){return btoa(String.fromCharCode(...new Uint8Array(bytes))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')}
async function startAwsLogin(){if(!runtimeConfig.cognitoDomain||!runtimeConfig.cognitoClientId||!runtimeConfig.awsApiBase){toast('尚未配置云端Outputs，请先部署template.yaml并生成cloud-config.js');return}const verifier=base64url(crypto.getRandomValues(new Uint8Array(48))),challenge=base64url(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(verifier)));sessionStorage.setItem('fj_pkce_verifier',verifier);const params=new URLSearchParams({client_id:runtimeConfig.cognitoClientId,response_type:'code',scope:(runtimeConfig.scopes||['openid','email']).join(' '),redirect_uri:runtimeConfig.cognitoRedirectUri,code_challenge:challenge,code_challenge_method:'S256'});location.href=`${runtimeConfig.cognitoDomain.replace(/\/$/,'')}/oauth2/authorize?${params}`}
async function handleAwsCallback(){const query=new URLSearchParams(location.search),code=query.get('code'),verifier=sessionStorage.getItem('fj_pkce_verifier');if(code&&verifier&&runtimeConfig.cognitoDomain){const body=new URLSearchParams({grant_type:'authorization_code',client_id:runtimeConfig.cognitoClientId,code,redirect_uri:runtimeConfig.cognitoRedirectUri,code_verifier:verifier});const res=await fetch(`${runtimeConfig.cognitoDomain.replace(/\/$/,'')}/oauth2/token`,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body});const tokens=await res.json();if(!res.ok)throw new Error(tokens.error_description||'Cognito令牌交换失败');state.awsToken=tokens.id_token||tokens.access_token;sessionStorage.setItem('fj_aws_token',state.awsToken);sessionStorage.removeItem('fj_pkce_verifier');history.replaceState({},document.title,location.pathname+location.hash)}state.awsConnected=Boolean(state.awsToken&&runtimeConfig.awsApiBase)}
function toggleAwsConnection(){if(state.awsConnected){state.awsToken='';state.awsConnected=false;state.cloud=null;sessionStorage.removeItem('fj_aws_token');renderChrome();render();toast('已断开AWS实时数据，切换为本地适配器')}else startAwsLogin()}
async function login(email,password){const out=await api('/auth/login',{method:'POST',body:JSON.stringify({email,password})});state.token=out.token;sessionStorage.setItem('fj_token',out.token);$('#loginView').classList.add('hidden');$('#shell').classList.remove('hidden');await Promise.all([api('/config').then(x=>state.config=x),load()]);}
async function logout(callApi=true){if(callApi&&state.token)try{await api('/auth/logout',{method:'POST'})}catch{}state.token='';state.data=null;sessionStorage.removeItem('fj_token');$('#shell').classList.add('hidden');$('#loginView').classList.remove('hidden');}
$('#loginForm').onsubmit=async e=>{e.preventDefault();$('#loginError').textContent='';const fd=new FormData(e.target);try{await login(fd.get('email'),fd.get('password'))}catch(err){$('#loginError').textContent=err.message}};
$('#awsConnectButton').onclick=toggleAwsConnection;$('#copilotButton').onclick=()=>navigate('copilot');$('#logoutButton').onclick=()=>logout();$('#refreshButton').onclick=async()=>{try{await load();toast('数据已刷新')}catch(err){toast(err.message)}};$('#menuButton').onclick=()=>$('#sidebar').classList.toggle('open');window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(pages[p]&&state.data)navigate(p)});
(async()=>{try{await handleAwsCallback();state.config=await api('/config');if(state.token){$('#loginView').classList.add('hidden');$('#shell').classList.remove('hidden');const initial=location.hash.slice(1);if(pages[initial])state.page=initial;await load();}}catch{logout(false)}})();
